		col = 0
	}
	if col > len(line) {
		col = len(line)
	}

	for _, token := range scanLineTokens(line) {
		if col < token.start || col > token.end {
			continue
		}
		return tokenContext{
			row:    row,
			start:  token.start,
			end:    token.end,
			prefix: string(line[token.start:col]),
			token:  token.text,
		}
	}

	return tokenContext{
		row:    row,
		start:  col,
		end:    col,
		prefix: "",
		token:  "",
	}
}

func scanLineTokens(line []rune) []lineToken {
	tokens := make([]lineToken, 0)
	col := 0
	for col < len(line) {
		for col < len(line) && unicode.IsSpace(line[col]) {
			col++
		}
		if col >= len(line) {
			break
		}

		start := col
		var quote rune
		escaped := false
		for col < len(line) {
			r := line[col]
			switch {
			case escaped:
				escaped = false
			case r == '\\' && quote != '\'':
				escaped = true
			case quote != 0:
				if r == quote {
					quote = 0
				}
			case r == '\'' || r == '"':
				quote = r
			case unicode.IsSpace(r):
				goto tokenDone
			}
			col++
		}
	tokenDone:
		tokens = append(tokens, lineToken{
			start: start,
			end:   col,
			text:  string(line[start:col]),
		})
	}
	return tokens
}

func withCursor(text string, col int) string {
	runes := []rune(text)
	if col < 0 {
		col = 0
	}
	if col > len(runes) {
		col = len(runes)
	}
	cursor := '█'
	if col == len(runes) {
		return string(append(runes, cursor))
	}
	out := make([]rune, 0, len(runes)+1)
	out = append(out, runes[:col]...)
	out = append(out, cursor)
	out = append(out, runes[col:]...)
	return string(out)
}

