	t.Logf("Completion active: %v, passive: %v", got.editor.completion.active, got.editor.completion.passive)
	t.Logf("Completion candidates: %d", len(got.editor.completion.candidates))
	for i, cand := range got.editor.completion.candidates {
		if i >= 5 {
			break
		}
		t.Logf("  Candidate %d: %q", i, cand.Text)
	}

	rendered := got.renderDetailLines(80, 10)
	for i, line := range rendered {
		if i >= 8 {
			break
		}
		fmt.Printf("Line %d: %s\n", i, line)
	}
